    62	function validate_draft_payload(array $payload): array
    63	{
    64	  $errors = [];
    65	  $clean = [];
    66	
    67	  $title = trim((string) ($payload['title'] ?? ''));
    68	  if ($title === '') {
    69	    $errors['title'] = 'Tiêu đề không được để trống.';
    70	  }
    71	  $clean['title'] = $title;
    72	
    73	  $excerpt = trim((string) ($payload['excerpt'] ?? ''));
    74	  if ($excerpt === '') {
    75	    $errors['excerpt'] = 'Mô tả ngắn không được để trống.';
    76	  }
    77	  $clean['excerpt'] = $excerpt;
    78	
    79	  $publishDate = normalize_date_ymd((string) ($payload['publish_date'] ?? ''));
    80	  if ($publishDate === '') {
    81	    $errors['publish_date'] = 'Ngày đăng không hợp lệ.';
    82	  }
    83	  $clean['publish_date'] = $publishDate;
    84	
    85	  $modifiedDateRaw = trim((string) ($payload['modified_date'] ?? ''));
    86	  $modifiedDate = $modifiedDateRaw === '' ? '' : normalize_date_ymd($modifiedDateRaw);
    87	  if ($modifiedDateRaw !== '' && $modifiedDate === '') {
    88	    $errors['modified_date'] = 'Ngày sửa không hợp lệ.';
    89	  }
    90	  if ($modifiedDate === '') {
    91	    $modifiedDate = date('Y-m-d');
    92	  }
    93	  $clean['modified_date'] = $modifiedDate;
    94	
    95	  $tagsInput = trim((string) ($payload['tags_text'] ?? ''));
    96	  $tags = array_values(array_unique(array_filter(array_map(static function (string $part): string {
    97	    return trim($part);
    98	  }, preg_split('/[,;\n]+/', $tagsInput) ?: []), static function (string $value): bool {
    99	    return $value !== '';
   100	  })));
   101	  if (count($tags) < 3) {
   102	    $errors['tags_text'] = 'Cần tối thiểu 3 tag.';
   103	  }
   104	  if (count($tags) > 7) {
   105	    $errors['tags_text'] = 'Tối đa 7 tag.';
   106	  }
   107	  $clean['tags'] = $tags;
   108	  $clean['tags_text'] = implode(', ', $tags);
   109	
   110	  $proseHtml = trim((string) ($payload['prose_html'] ?? ''));
   111	  if ($proseHtml === '') {
   112	    $errors['prose_html'] = 'Nội dung chính không được để trống.';
   113	  }
   114	  $clean['prose_html'] = $proseHtml;
   115	
   116	  return [
   117	    'ok' => empty($errors),
   118	    'errors' => $errors,
   119	    'data' => $clean,
   120	  ];
   121	}
